import type {ImageDefinition} from '../types/types'
import styles from '../styles/components/ImageHeaderDescription.module.css'
import type {RetentionPolicies} from '../types/payloads'

interface CustomImagesViewSummaryProps {
  customImages: ImageDefinition[]
  ownerId: string
  retentionPolicies: RetentionPolicies
}

export function CustomImagesViewSummary(props: CustomImagesViewSummaryProps) {
  const totalImageVersions = props.customImages.reduce((sum, img) => sum + (img.imageVersionsCount ?? 0), 0)
  const totalImagesSizeGb = props.customImages.reduce((sum, img) => sum + (img.totalImageVersionsSizeGb ?? 0), 0)

  return (
    <div className={styles.headerContainer}>
      <div className="col-6 d-inline-block v-align-top">
        <div>
          <span className="color-fg-muted">Global ID: </span>
          <span>{props.ownerId}</span>
        </div>
        <div>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <span className="color-fg-muted">Image Versions Count: </span>
          <span>{totalImageVersions}</span>
        </div>
        <div>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <span className="color-fg-muted">Total Size: </span>
          <span>{totalImagesSizeGb} GB</span>
        </div>
      </div>
      <div className="col-6 d-inline-block v-align-top">
        <div>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <span className="color-fg-muted">Retention Policies: </span>
          <br />
          <span>- ImageVersionsPerImage: {props.retentionPolicies.imageVersionsPerImageLimit}</span>
          <br />
          <span>- ImageVersionsUnusedAge: {props.retentionPolicies.imageVersionUnusedAgeLimit} days</span>
          <br />
          <span>- ImageVersionsMaxAge: {props.retentionPolicies.imageVersionMaxAgeLimit} days</span>
        </div>
      </div>
    </div>
  )
}
